"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9167],{61981:n=>{n.exports=JSON.parse('{"functions":[{"name":".","desc":"Property or instance method. The default accessor.\\n\\n**Syntax:** `obj.Prop` \xb7 `obj.Method(args)`\\n\\n**Emit:** `obj.Prop` / `obj:Method(args)`\\n\\n```clpp\\nplayer.Name = \\"Kartz\\";\\nplayer.Kick();\\nworkspace.FindFirstChild(\\"x\\");\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":38,"path":"moonwave/Operators.lua"}},{"name":":","desc":"Type annotation, or a protected (Safe Mode) call.\\n\\n**Syntax:** `age: int = 10` \xb7 `player:Kick()`\\n\\n**Emit:** `local age: number = 10` / `pcall` of the method; `nil` on error.\\n\\n```clpp\\nage: int = 10;\\nauto child = workspace:FindFirstChild(\\"x\\");\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":55,"path":"moonwave/Operators.lua"}},{"name":"::","desc":"Static scope, class method definition, or a Connect you Disconnect yourself.\\n\\n**Syntax:** `task::wait(1)` \xb7 `Class::Method` \xb7 `players.PlayerAdded::Connect(fn)`\\n\\n**Emit:** `task.wait(1)` / `function Class:Method` / `signal:Connect(fn)` (no Janitor)\\n\\n```clpp\\nplayers.PlayerAdded::Connect(fn);\\ntask::wait(1);\\n```\\n\\nDatatype / `task::wait` emit `.`. Prefer `~>` when a janitor should own the connection.","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":74,"path":"moonwave/Operators.lua"}},{"name":".:","desc":"String concatenation. Never `+` or Lua `..`.\\n\\n**Syntax:** `a .: b .: c`\\n\\n**Emit:** `a .. b` (left-associative)\\n\\n```clpp\\nreturn player.Name .: \\"_LeaderstatsJanitor\\";\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":90,"path":"moonwave/Operators.lua"}},{"name":"~>","desc":"Subscribe and give the connection to Janitor. `~>Connect` and `~>Once` only.\\n\\n**Syntax:** `signal~>Connect(fn);` \xb7 `signal~>Once(fn);`\\n\\n**Emit:** `janitor:Add(signal:Connect(fn), \\"Disconnect\\")`\\n\\nLooks up `janitor` local, `self.janitor`, or synthetic `__janitor`.","params":[{"name":"fn","desc":"Listener","lua_type":"func"}],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":105,"path":"moonwave/Operators.lua"}},{"name":"[]","desc":"Index an array, map, or Roblox child by dynamic name. Not a lambda capture.\\n\\n**Syntax:** `items[0]` \xb7 `data[\\"Coins\\"]` \xb7 `workspace[\\"PlayerCharacter\\"]`\\n\\n**Emit:** `items[0]` / `data[\\"Coins\\"]` / `workspace[\\"PlayerCharacter\\"]`\\n\\n```clpp\\nstring first = items[0];\\nplayerData[\\"Coins\\"] = 600;\\nInstance root = character[\\"HumanoidRootPart\\"];\\n```","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":123,"path":"moonwave/Operators.lua"}},{"name":"+","desc":"Numeric arithmetic. `+` does not concatenate. `*` is never pointer deref.\\n\\n**Syntax:** `a + b - c * d / e`\\n\\n**Emit:** same operators","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":135,"path":"moonwave/Operators.lua"}},{"name":"!=","desc":"`!=` emits `~=`. The others stay the same.\\n\\n**Syntax:** `a != b` \xb7 `a == b`\\n\\n**Emit:** `~=` / `==` / `<` / `>` / `<=` / `>=`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":147,"path":"moonwave/Operators.lua"}},{"name":"&&","desc":"Boolean logic. No ternary `? :`.\\n\\n**Syntax:** `a && b || !c`\\n\\n**Emit:** `and` / `or` / `not`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":159,"path":"moonwave/Operators.lua"}},{"name":"=","desc":"Assignment and compound assignment. Observable assignment writes `.Value`.\\n\\n**Syntax:** `name = value;` \xb7 `name += 1;`\\n\\n**Emit:** `=` `+=` `-=` `**=` `/=`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":171,"path":"moonwave/Operators.lua"}},{"name":"++","desc":"Always emits `+= 1` / `-= 1`. Prefix/postfix value is not preserved.\\n\\n**Syntax:** `i++;` \xb7 `i--;`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":181,"path":"moonwave/Operators.lua"}},{"name":".Field","desc":"C++ designated initializer \u2192 Luau table field.\\n\\n**Syntax:** `Type { .Field = value }`\\n\\n**Emit:** `{ Field = value }`","params":[],"returns":[],"function_type":"static","tags":["operator"],"source":{"line":193,"path":"moonwave/Operators.lua"}}],"properties":[],"types":[],"name":"Operators","desc":"CL++ does **not** use `->`. `.` is the default (property and instance method). `:` types and protects calls. `::` is static / manual Connect. `~>` is Janitor. `[]` indexes arrays, maps, and dynamic child names \u2014 never a C++ capture list. Callbacks are `func (params) { }`.\\n\\n| Operator | Meaning | Luau |\\n| --- | --- | --- |\\n| `.` | property / instance method | `.` / `:` on a call |\\n| `:` | type annotation / protected call | `pcall` on a call |\\n| `::` | static scope / manual Connect | `.` / `:` |\\n| `[]` | array / map / dynamic child index | `[key]` |\\n| `.:` | string concatenation | `..` |\\n| `~>` | Connect / Once with Janitor | `janitor:Add(..., \\"Disconnect\\")` |\\n\\n`+` only adds numbers. `!=` `&&` `||` `!` emit `~=` `and` `or` `not`. `++` / `--` emit `+= 1` / `-= 1`.\\n\\nFull pages: [Language reference \u2014 Operators](/CLPP/docs/reference).","source":{"line":20,"path":"moonwave/Operators.lua"}}')}}]);